using UnityEngine;

namespace Eleven.Host
{
    /// <summary>
    /// Builds the host at runtime, so no scene needs hand editing: the build's only scene is an
    /// empty one generated by the batch-mode build script.
    /// </summary>
    internal static class HostBootstrap
    {
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        private static void Create()
        {
            var host = new GameObject("ELEVEN host");
            host.AddComponent<HostLoop>();
        }
    }
}
